package com.unicare.dispensary.message;import jakarta.validation.Valid;import java.security.Principal;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController public class MessageController{private final MessageService service;public MessageController(MessageService s){service=s;}@GetMapping("/api/messages/my")public List<MessageResponse> mine(Principal p){return service.mine(p.getName());}@PostMapping("/api/messages")@ResponseStatus(HttpStatus.CREATED)public MessageResponse create(@Valid @RequestBody MessageRequest r,Principal p){return service.create(p.getName(),r);}@GetMapping("/api/staff/messages")public List<MessageResponse> all(){return service.all();}@PostMapping("/api/staff/messages/{id}/reply")public MessageResponse reply(@PathVariable Long id,@Valid @RequestBody ReplyRequest r,Principal p){return service.reply(id,p.getName(),r.body());}@PatchMapping("/api/staff/messages/{id}/close")public MessageResponse close(@PathVariable Long id){return service.closeWithBody(id);}}
